//! Parity with golden statistics generated by the original Python implementation.
use super::emulate::emulate;
use super::glyphs::{set_font_raster, Bits, Face, FontRaster, GridSpec};
use super::model::EmuOptions;
use std::collections::BTreeMap;

pub struct MockRaster;
fn eff_idx(ch: char, face: Face) -> u32 {
    if (ch as u32) > 0x2FF {
        return 3;
    }
    match face {
        Face::Roman => 0,
        Face::Sans => 1,
        Face::Courier => 2,
    }
}
impl FontRaster for MockRaster {
    fn bits(&self, ch: char, face: Face, spec: &GridSpec, cols: usize, _t: f32) -> Bits {
        let fi = eff_idx(ch, face);
        let mut b = Bits::zeros(spec.rows, cols);
        for r in 0..spec.rows {
            for c in 0..cols {
                if ((ch as u32) * 31 + r as u32 * 7 + c as u32 * 13 + fi * 3) % 5 < 2 {
                    b.d[r * cols + c] = 1;
                }
            }
        }
        b
    }
    fn advance_px(&self, ch: char, _face: Face, cap_px: i32) -> f32 {
        4.0 + ((ch as u32) % 7) as f32 + cap_px as f32 * 0.5
    }
}

fn root() -> std::path::PathBuf {
    std::path::PathBuf::from(std::env::var("RDM_ROOT").unwrap_or_else(|_| env!("CARGO_MANIFEST_DIR").to_string()))
}

#[derive(Debug, Default, Clone)]
struct PageStat {
    n: usize,
    w: f64,
    h: f64,
    unknown: usize,
    sx: f64,
    sy: f64,
    xb: u64,
    yb: u64,
    spin: i64,
    spass: i64,
    sdir: i64,
    scol: i64,
    pk: String,
}

#[derive(Debug, Default)]
struct DocStat {
    n_pages: usize,
    n_unknown: usize,
    carriage: f64,
    opts: String,
    detected: String,
    warnings: usize,
    fixes: usize,
    notes: usize,
    n_bytes: usize,
    pages: Vec<PageStat>,
}

fn load(file: &str) -> BTreeMap<String, DocStat> {
    let txt = std::fs::read_to_string(root().join("tests/golden").join(file)).expect("golden file");
    let mut m: BTreeMap<String, DocStat> = BTreeMap::new();
    for line in txt.lines() {
        let f: Vec<&str> = line.split('\t').collect();
        let d = m.entry(f[0].to_string()).or_default();
        if f[1] == "DOC" {
            d.n_pages = f[2].parse().unwrap();
            d.n_unknown = f[3].parse().unwrap();
            d.carriage = f[4].parse().unwrap();
            d.opts = f[5].to_string();
            d.detected = f[6].to_string();
            d.warnings = f[7].parse().unwrap();
            d.fixes = f[8].parse().unwrap();
            d.notes = f[9].parse().unwrap();
            d.n_bytes = f[10].parse().unwrap();
        } else {
            d.pages.push(PageStat {
                n: f[2].parse().unwrap(),
                w: f[3].parse().unwrap(),
                h: f[4].parse().unwrap(),
                unknown: f[5].parse().unwrap(),
                sx: f[6].parse().unwrap(),
                sy: f[7].parse().unwrap(),
                xb: f[8].parse().unwrap(),
                yb: f[9].parse().unwrap(),
                spin: f[10].parse().unwrap(),
                spass: f[11].parse().unwrap(),
                sdir: f[12].parse().unwrap(),
                scol: f[13].parse().unwrap(),
                pk: f[14].to_string(),
            });
        }
    }
    m
}

pub fn opts_from(s: &str, printer: &str) -> EmuOptions {
    let mut o = EmuOptions { printer: printer.into(), ..Default::default() };
    for kv in s.split(';').filter(|x| !x.is_empty()) {
        let (k, v) = kv.split_once('=').unwrap();
        let b = v == "True";
        match k {
            "esc_a_immediate" => o.esc_a_immediate = b,
            "codepage" => o.codepage = v.into(),
            "blank_lines" => o.blank_lines = v.into(),
            "honor_page_length" => o.honor_page_length = b,
            "force_nlq" => o.force_nlq = Some(b),
            "auto_wrap" => o.auto_wrap = b,
            "page_length_in" => o.page_length_in = v.parse().unwrap(),
            "mps_gap" => o.mps_gap = v.into(),
            "cbm_charset" => o.cbm_charset = v.into(),
            "cr_adds_lf" => o.cr_adds_lf = Some(b),
            "lf_adds_cr" => o.lf_adds_cr = Some(b),
            "wide_carriage" => o.wide_carriage = Some(b),
            _ => panic!("unknown option {k}"),
        }
    }
    o
}

fn close(a: f64, b: f64) -> bool {
    (a - b).abs() <= 1e-6 * b.abs().max(1.0)
}

pub fn check(file: &str, names_filter: Option<&dyn Fn(&str) -> bool>) -> usize {
    set_font_raster(Box::new(MockRaster));
    let gold = load(file);
    let mut bad: Vec<String> = Vec::new();
    let mut n = 0;
    for (key, g) in &gold {
        let (name, printer) = key.split_once('|').unwrap();
        if let Some(f) = names_filter {
            if !f(key) {
                continue;
            }
        }
        n += 1;
        let path = root().join("tests/golden/inputs").join(format!("{name}.bin"));
        let data = std::fs::read(&path).unwrap_or_else(|_| panic!("{path:?}"));
        let doc = emulate(&data, &opts_from(&g.opts, printer));
        let mut errs = Vec::new();
        if doc.pages.len() != g.n_pages {
            errs.push(format!("pages {} != {}", doc.pages.len(), g.n_pages));
        }
        if doc.n_unknown != g.n_unknown {
            errs.push(format!("n_unknown {} != {}", doc.n_unknown, g.n_unknown));
        }
        if doc.detected != g.detected {
            errs.push(format!("detected {:?} != {:?}", doc.detected, g.detected));
        }
        if doc.warnings.len() != g.warnings {
            errs.push(format!("warnings {} != {} ({:?})", doc.warnings.len(), g.warnings, doc.warnings));
        }
        if doc.fixes.len() != g.fixes || doc.notes.len() != g.notes || doc.n_bytes != g.n_bytes {
            errs.push(format!("fixes/notes/bytes {}/{}/{} != {}/{}/{}", doc.fixes.len(), doc.notes.len(), doc.n_bytes, g.fixes, g.notes, g.n_bytes));
        }
        if !close(doc.carriage_in, g.carriage) {
            errs.push(format!("carriage {} != {}", doc.carriage_in, g.carriage));
        }
        for (i, (p, s)) in doc.pages.iter().zip(&g.pages).enumerate() {
            let xb: u64 = p.x.iter().map(|v| v.to_bits() as u64).sum();
            let yb: u64 = p.y.iter().map(|v| v.to_bits() as u64).sum();
            let sx: f64 = p.x.iter().map(|&v| v as f64).sum();
            let sy: f64 = p.y.iter().map(|&v| v as f64).sum();
            let spin: i64 = p.pin.iter().map(|&v| v as i64).sum();
            let spass: i64 = p.pass_no.iter().map(|&v| v as i64).sum();
            let sdir: i64 = p.dirn.iter().map(|&v| v as i64).sum();
            let scol: i64 = p.color.as_ref().map(|c| c.iter().map(|&v| v as i64).sum()).unwrap_or(-1);
            let mut e = Vec::new();
            if p.n_dots() != s.n { e.push(format!("n {} != {}", p.n_dots(), s.n)); }
            if !close(p.width_in, s.w) || !close(p.height_in, s.h) { e.push(format!("size {}x{} != {}x{}", p.width_in, p.height_in, s.w, s.h)); }
            if p.unknown != s.unknown { e.push(format!("unknown {} != {}", p.unknown, s.unknown)); }
            if !close(sx, s.sx) { e.push(format!("sx {sx} != {}", s.sx)); }
            if !close(sy, s.sy) { e.push(format!("sy {sy} != {}", s.sy)); }
            if xb != s.xb || yb != s.yb { e.push(format!("bits differ (x {} y {}) though sums close={}", xb != s.xb, yb != s.yb, close(sx, s.sx) && close(sy, s.sy))); }
            if spin != s.spin { e.push(format!("pin {spin} != {}", s.spin)); }
            if spass != s.spass { e.push(format!("pass {spass} != {}", s.spass)); }
            if sdir != s.sdir { e.push(format!("dir {sdir} != {}", s.sdir)); }
            if scol != s.scol { e.push(format!("col {scol} != {}", s.scol)); }
            if p.profile_key != s.pk { e.push(format!("profile_key {:?} != {:?}", p.profile_key, s.pk)); }
            if !e.is_empty() {
                errs.push(format!("page {i}: {}", e.join(", ")));
            }
        }
        if !errs.is_empty() {
            bad.push(format!("{key}: {}", errs.join(" | ")));
        }
    }
    if !bad.is_empty() {
        let shown: Vec<String> = bad.iter().take(25).cloned().collect();
        panic!("{} of {} golden cases differ:\n{}", bad.len(), n, shown.join("\n"));
    }
    n
}

#[test]
fn emulate_matches_python() {
    let n = check("emulate.tsv", None);
    assert!(n > 300);
}

#[test]
fn detection_matches_python() {
    use super::detect::*;
    let txt = std::fs::read_to_string(root().join("tests/golden/detect.tsv")).unwrap();
    let mut bad: Vec<String> = Vec::new();
    let mut n = 0;
    for line in txt.lines() {
        let f: Vec<&str> = line.split('\t').collect();
        let name = f[0];
        let data = std::fs::read(root().join("tests/golden/inputs").join(format!("{name}.bin"))).unwrap();
        n += 1;
        let mut errs: Vec<String> = Vec::new();
        let det = detect_printer(&data);
        if det != f[1] {
            errs.push(format!("detect {det} != {}", f[1]));
        }
        let sc = score_printers(&data);
        for kv in f[2].split(',') {
            let (k, v) = kv.split_once('=').unwrap();
            let want: f64 = v.parse().unwrap();
            let got = score_get(&sc, k);
            if (got - want).abs() > 1e-9 {
                errs.push(format!("score {k} {got} != {want}"));
            }
        }
        let segs: Vec<String> = split_segments(&data).iter().map(|(a, b, k)| format!("{a}-{b}-{k}")).collect();
        if segs.join(";") != f[3] {
            errs.push(format!("segments {} != {}", segs.join(";"), f[3]));
        }
        if unfinished_graphics(&data) != (f[4] == "1") {
            errs.push("unfinished_graphics".into());
        }
        if is_probe(&data) != (f[5] == "1") {
            errs.push("is_probe".into());
        }
        let (und, note) = undouble(&data);
        if und.len().to_string() != f[6] || note != f.get(8).copied().unwrap_or("") {
            errs.push(format!("undouble {} {:?} != {} {:?}", und.len(), note, f[6], f.get(8)));
        }
        let msum: u64 = mask_graphics(&data).iter().map(|&b| b as u64).sum();
        if msum.to_string() != f[7] {
            errs.push(format!("mask sum {msum} != {}", f[7]));
        }
        if !errs.is_empty() {
            bad.push(format!("{name}: {}", errs.join(" | ")));
        }
    }
    assert!(n > 100);
    assert!(bad.is_empty(), "{} of {} differ:\n{}", bad.len(), n, bad.iter().take(20).cloned().collect::<Vec<_>>().join("\n"));
}

#[test]
fn analyze_matches_python() {
    use super::analyze::classify;
    let txt = std::fs::read_to_string(root().join("tests/golden/analyze.tsv")).unwrap();
    let mut want: BTreeMap<String, Vec<(String, String)>> = BTreeMap::new();
    for line in txt.lines() {
        let f: Vec<&str> = line.split('\t').collect();
        want.entry(f[0].to_string()).or_default().push((f[2].to_string(), f.get(3).unwrap_or(&"").to_string()));
    }
    let gold = load("emulate.tsv");
    let mut bad = Vec::new();
    for (key, w) in &want {
        let (name, printer) = key.split_once('|').unwrap();
        let data = std::fs::read(root().join("tests/golden/inputs").join(format!("{name}.bin"))).unwrap();
        set_font_raster(Box::new(MockRaster));
        let doc = emulate(&data, &opts_from(&gold[key].opts, printer));
        let got: Vec<(String, String)> = classify(&doc).iter().map(|i| (i.kind.as_str().to_string(), i.reason.clone())).collect();
        if &got != w {
            bad.push(format!("{key}: {:?} != {:?}", got, w));
        }
    }
    assert!(bad.is_empty(), "{} differ:\n{}", bad.len(), bad.iter().take(10).cloned().collect::<Vec<_>>().join("\n"));
}
